<?php $title='Salary & Payroll'; require_once __DIR__.'/../partials/header.php'; $db=new Database(); $c=$db->getConnection(); $employees=$c->query("SELECT id,employee_code,name,basic_salary FROM employees WHERE status='active' ORDER BY name")->fetch_all(MYSQLI_ASSOC); $m=new Salary($c); if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??null);$m->save(['employee_id'=>(int)$_POST['employee_id'],'salary_month'=>$_POST['salary_month'],'basic_salary'=>(float)$_POST['basic_salary'],'allowance'=>(float)$_POST['allowance'],'overtime'=>(float)$_POST['overtime'],'deduction'=>(float)$_POST['deduction']]);redirect('salary.php');}catch(Throwable $e){$error=$e->getMessage();}} $rows=$m->all(); ?>
<section class="panel"><?php if(!empty($error)):?><div class="alert"><?=e($error)?></div><?php endif;?><div class="panel-head"><h2>Generate / Update Monthly Salary</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Employee</label><select class="select" id="employee" name="employee_id" required><?php foreach($employees as $e):?><option value="<?=$e['id']?>" data-salary="<?=$e['basic_salary']?>"><?=e($e['employee_code'].' — '.$e['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Salary Month</label><input class="input" type="month" name="salary_month" value="<?=date('Y-m')?>" required></div><div class="field"><label>Basic Salary</label><input class="input" id="basic" type="number" step="0.01" name="basic_salary" value="0" required></div><div class="field"><label>Allowance</label><input class="input" type="number" step="0.01" name="allowance" value="0"></div><div class="field"><label>Overtime</label><input class="input" type="number" step="0.01" name="overtime" value="0"></div><div class="field"><label>Deduction</label><input class="input" type="number" step="0.01" name="deduction" value="0"></div><div><button class="btn btn-primary">Save Payroll</button></div></form></section><section class="panel"><div class="panel-head"><h2>Payroll History</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Month</th><th>Employee</th><th>Basic</th><th>Allowance</th><th>Overtime</th><th>Deduction</th><th>Net Salary</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['salary_month'])?></td><td><?=e($r['employee_code'].' — '.$r['name'])?></td><td>₹<?=number_format($r['basic_salary'],2)?></td><td>₹<?=number_format($r['allowance'],2)?></td><td>₹<?=number_format($r['overtime'],2)?></td><td>₹<?=number_format($r['deduction'],2)?></td><td><strong>₹<?=number_format($r['net_salary'],2)?></strong></td></tr><?php endforeach;?></tbody></table></div></section><?php require_once __DIR__.'/../partials/footer.php'; ?>
